"""Writes expected.inc for test/spring_bone_test.cpp from the offline reference solver.

    python3 test/fixtures/spring_bone/gen.py <path to p39_spring_solver.py>

The reference solver (numpy) lives with the Sorcerer art outside Git: sorcerer/prep_candidate1_20261017/
39_spring_chain_rig_round2_20261027_v1/p39_spring_solver.py, sha256 4bb167e4... Two toy scenes, 120 fixed steps each:
  chain: a 3-joint chain (plus tip) hanging from a moving, turning parent, with gravity and one capsule it hits;
  blend: the same chain with a parentBlend root (0.6 on a second body node that moves on its own, 0.4 on the parent).
Recorded per step: every joint tail; every 10th step also the joints' world matrices (3x4, row major).
"""
import hashlib, importlib.util, json, os, sys

import numpy as np

src = sys.argv[1]
spec = importlib.util.spec_from_file_location('p39', src)
p39 = importlib.util.module_from_spec(spec)
spec.loader.exec_module(p39)
sha = hashlib.sha256(open(src, 'rb').read()).hexdigest()

DT = p39.DT
STEPS = 120
P = dict(stiffness=1.0, gravityPower=0.7, gravityDir=[0.0, -1.0, 0.0], dragForce=0.4, hitRadius=0.02)
Q_ID = [0.0, 0.0, 0.0, 1.0]
DOWN = [0.0, -0.1, 0.0]


def rot(axis, ang):
    axis = p39.normalize(np.asarray(axis, float))
    K = np.array([[0, -axis[2], axis[1]], [axis[2], 0, -axis[0]], [-axis[1], axis[0], 0]])
    return np.eye(3) + np.sin(ang) * K + (1 - np.cos(ang)) * K @ K


def parent_pose(t):  # node 0: moves and turns about Z
    W = np.eye(4); W[:3, :3] = rot([0, 0, 1], 0.8 * np.sin(1.7 * t)); W[:3, 3] = [0.3 * np.sin(2 * t), 0.1 * np.cos(3 * t), 0.2 * np.sin(t)]
    return W


R1 = np.eye(4); R1[:3, :3] = rot([0.3, 0.2, 1.0], 0.4); R1[:3, 3] = [0.08, -0.05, 0.02]  # rest global of node 1


def node1_pose(t):  # node 1: turns about its own axis and drifts
    W = np.eye(4); W[:3, :3] = rot([0.1, 1.0, 0.3], 0.9 * np.sin(2.3 * t)) @ R1[:3, :3]
    W[:3, 3] = R1[:3, 3] + [0.1 * np.sin(3 * t), 0.05 * np.cos(t), 0.0]
    return W


rootL = np.eye(4); rootL[:3, :3] = rot([1, 0, 0.2], 0.3); rootL[:3, 3] = [0.03, -0.02, 0.01]  # blend root local rest
off0 = rootL                                   # root rest global in node 0's rest frame (node 0 rest = identity)
off1 = np.linalg.inv(R1) @ rootL               # ... and in node 1's


def trs(M):
    return {'translation': M[:3, 3].tolist(), 'rotation': p39.mat3_to_quat(M[:3, :3]).tolist()}


def joints(first):  # joint nodes first..first+2 plus the tip first+3
    return [dict(P, node=first + k) for k in range(3)] + [{'node': first + 3}]


chain_extras = {'DAMNATIONX_springBone': {
    'colliders': [{'node': 0, 'shape': {'capsule': {'offset': [-0.2, -0.15, 0.03], 'tail': [0.2, -0.15, 0.03], 'radius': 0.05}}}],
    'colliderGroups': [{'colliders': [0]}],
    'springs': [{'parentNode': 0, 'joints': joints(1), 'colliderGroups': [0]}]}}
chain_local = {1: ([0.0, 0.0, 0.0], Q_ID), 2: (DOWN, Q_ID), 3: (DOWN, Q_ID), 4: (DOWN, Q_ID)}

blend_extras = {'DAMNATIONX_springBone': {
    'colliders': [], 'colliderGroups': [],
    'springs': [{'parentNode': 0, 'joints': joints(2), 'colliderGroups': [],
                 'parentBlend': [dict(node=0, weight=0.4, restOffset=trs(off0)), dict(node=1, weight=0.6, restOffset=trs(off1))]}]}}
blend_local = {2: (rootL[:3, 3].tolist(), p39.mat3_to_quat(rootL[:3, :3]).tolist()), 3: (DOWN, Q_ID), 4: (DOWN, Q_ID), 5: (DOWN, Q_ID)}


def run(extras, local, pose):
    springs = p39.springs_from_extras(extras['DAMNATIONX_springBone'], lambda i: tuple(np.asarray(v, float) for v in local[i]))
    p39.reset(springs, pose(0.0))
    tails, worlds = [], []
    for k in range(STEPS):
        out = p39.step(springs, pose(k * DT))
        tails.append([j.tail.tolist() for j in springs[0].joints])
        if k % 10 == 9:
            worlds.append([out[j.node][:3, :].flatten().tolist() for j in springs[0].joints])
    return tails, worlds


def floats(values):
    return '{ ' + ', '.join('%.8g' % v for v in np.asarray(values).flatten()) + ' }'


chain = run(chain_extras, chain_local, lambda t: {0: parent_pose(t)})
blend = run(blend_extras, blend_local, lambda t: {0: parent_pose(t), 1: node1_pose(t)})

lines = ['// Generated by test/fixtures/spring_bone/gen.py from p39_spring_solver.py (sha256 %s); do not edit.' % sha,
         'constexpr int FixtureSteps = %d;' % STEPS,
         'constexpr char ChainExtras[] = R"(%s)";' % json.dumps(chain_extras),
         'constexpr char BlendExtras[] = R"(%s)";' % json.dumps(blend_extras),
         'constexpr float BlendRootT[3] = %s;' % floats(blend_local[2][0]),
         'constexpr float BlendRootQ[4] = %s;' % floats(blend_local[2][1])]
for name, (tails, worlds) in (('Chain', chain), ('Blend', blend)):
    lines.append('constexpr float %sTails[%d][3][3] = { %s };' % (name, STEPS, ', '.join('{ %s }' % ', '.join(floats(t) for t in step) for step in tails)))
    lines.append('constexpr float %sWorlds[%d][3][12] = { %s };' % (name, len(worlds), ', '.join('{ %s }' % ', '.join(floats(w) for w in step) for step in worlds)))
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'expected.inc')
open(out, 'w').write('\n'.join(lines) + '\n')
print(out, os.path.getsize(out))
